window.AUTH=window.AUTH||{};window.AUTH["20-472"]={"d":"20-472","id":"2020/20-472","n":"HollyFrontier Cheyenne Refining LLC v. Renewable Fuels Association","briefs":[{"k":"petitioner","label":"Brief of petitioners HollyFrontier Cheyenne Refining, LLC, et al.","date":"2021-02-22","url":"https://www.supremecourt.gov/DocketPDF/20/20-472/169592/20210222155902550_Brief%20of%20Petitioners.pdf","side":"pet","n":63},{"k":"respondent","label":"Brief of Federal Respondent","date":"2021-03-24","url":"https://www.supremecourt.gov/DocketPDF/20/20-472/172882/20210324163338826_20-472bsUnitedStates.pdf","side":"res","n":69},{"k":"respondent","label":"Brief of respondents Renewable Fuels Association, et al.","date":"2021-03-24","url":"https://www.supremecourt.gov/DocketPDF/20/20-472/172849/20210324142359023_2021.03.24%20Biofuels%20Coalition%20Brief%20in%20Response%2020472.pdf","side":"res","n":51},{"k":"reply","label":"Reply of petitioners HollyFrontier Cheyenne Refining, LLC, et al.","date":"2021-04-15","url":"https://www.supremecourt.gov/DocketPDF/20/20-472/175821/20210415135526409_Reply%20Brief.pdf","side":"pet","n":24}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/594us2r58_6537.pdf","tr":true,"items":[{"t":"case","label":"Ali v. Fed. Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"AT&T Corp. v. Iowa Utils. Bd.","cite":"525 U.S. 366","y":1999,"id":"1998/97-826","sc":1,"op":2,"sum":"In a complicated split opinion, the Court held that the FCC has rulemaking authority to uphold those provision of the Act in question. Despite the local nature of some of the LECs involved, the Court emphasized their interconnectivity with regional and national carriers. As such, the FCC could also reach local LEC markets and regulate their competitive business practices.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Barber v. Thomas","cite":"560 U.S. 474","y":2010,"id":"2009/09-5201","sc":1,"sum":"The Court held that the Federal Bureau of Prisons' method of determining \"good behavior,\" which was based on the inmate's time in prison rather than the overall sentence, was constitutional.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Barr v. Am. Ass’n of Political Consultants, Inc.","cite":"140 S. Ct. 2335","y":2020,"id":"2019/19-631","sc":1,"sum":"The Court held that a provision of the Telephone Consumer Protection Act of 1991 creating an exception to the prohibition on automated calls for government debt collection calls violates the First Amendment but is severable from the remainder of the statute.","sumSrc":"Oyez","by":{"0":"24, 25"}},{"t":"case","label":"Burwell v. Hobby Lobby Stores, Inc.","cite":"573 U.S. 682","y":2014,"id":"2013/13-354","sc":1,"sum":"The Court decided that the Affordable Care Act's requirement of for-profit corporations to supply its employees with contraceptives that go against the owners' beliefs is unconstitutional under the Religious Freedom Restoration Act of 1993.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Campbell River Timber Co. v. Vierhus","cite":"86 F.2d 673","y":1936,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/86/673/","by":{"0":"31"}},{"t":"case","label":"Chevron U.S.A., Inc. v. Nat. Res. Def. Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"op":3,"ar":12,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"46","1":"45, 46","2":"passim"}},{"t":"case","label":"Credit Suisse Sec. (USA) LLC v. Simmonds","cite":"566 U.S. 221","y":2012,"id":"2011/10-1261","sc":1,"op":1,"sum":"The Court held that Section 16(b) of the 1934 Securities Exchange Act is subject to tolling, where tolling starts after the filing of a Section 16(a) claim.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Envtl. Def. v. Duke Energy Corp.","cite":"549 U.S. 561","y":2007,"id":"2006/05-848","sc":1,"sum":"Unanswered and No. In a unanimous opinion by Justice David Souter, the Court ruled that the EPA need not interpret \"modification\" in PSD regulations the same way the term is interpreted in NSPS regulations. The Court's opinion acknowledged that two occurrences of the same term - sharing the same definition - are normally given the same meaning.","sumSrc":"Oyez","by":{"0":"27","2":"36"}},{"t":"case","label":"Field v. Mans","cite":"157 F.3d 35","y":1998,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/157/35/","by":{"0":"23","2":"27"}},{"t":"case","label":"Gen. Dynamics Land Sys., Inc. v. Cline","cite":"540 U.S. 581","y":2004,"id":"2003/02-1080","sc":1,"sum":"Justice David H. Souter delivered the Court's 6-3 opinion that the Age Discrimination in Employment Act's \"text, structure, purpose, history, and relationship to other federal statutes show that the statute does not mean to stop an employer from favoring an older employee over a younger one.\" The Court cited a long-held understanding of the \"ADEA as a remedy for unfair preference based on relative youth, leaving complaints of the relatively young outside the statutory concern.\" The Court also noted the findings section of the act included no evidence of younger workers being discriminated against in favor of older workers.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Golan v. Holder","cite":"565 U.S. 302","y":2012,"id":"2011/10-545","sc":1,"sum":"The Court held that Section 514 of the Uruguay Round Agreements Act, regarding copyright status of works in the public domain, does not violate the Copyright Clause or the First Amendment.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Graham Cty. Soil & Water Conservation Dist. v. United States ex rel. Wilson","cite":"559 U.S. 280","y":2010,"id":"2009/08-304","sc":1,"sum":"The Court held that an audit performed by a state or its political subdivisions constitutes an administrative report within the False Claims Act.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Harrison v. PPG Indus., Inc.","cite":"446 U.S. 578","y":1980,"id":"1979/78-1918","sc":1,"sum":"The phrase \"any other final action\" in § 307 (b) (1) is to be construed in accordance with its literal meaning so as to reach any action of the Administrator that is final, not just final actions of the Administrator similar to actions under the specifically enumerated provisions that precede the catchall phrase in the statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"Hermes Consol., LLC v. EPA","cite":"787 F.3d 568","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/787/568/","by":{"0":"9","1":"18, 27, 28","2":"8, 9, 32, 42"}},{"t":"case","label":"Idaho Sheet Metal Works, Inc., v. Wirtz","cite":"383 U.S. 190","y":1966,"id":"1965/30","sc":1,"sum":"In No. 30 the employer, petitioner, has 12 workers who fabricate, install and repair sheet metal products. While about 60% of sales in number are to the general public, about 83% of gross income comes from Work done, generally on individual specifications for sizable pieces of equipment, for five potato processing companies which dehydrate and freeze potatoes for interstate shipment. In reply to respondent's claim …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Page Little Sisters of the Poor Saints Peter & Paul Home v. Pennsylvania","cite":"140 S. Ct. 2367","y":2020,"id":"2019/19-431","sc":1,"sum":"The Court held that the federal government acted properly when it added extensive exemptions to regulations requiring employers to include contraceptive coverage in employee health plans.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Nat’l Ass’n of Home Builders v. Defs. of Wildlife","cite":"551 U.S. 644","y":2007,"id":"2006/06-340","sc":1,"sum":"The majority opinion held that Section 7(a)(2)'s provisions for protecting endangered species do not establish a \"tenth criterion\" for the EPA to consider before transferring permitting authority.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Nat’l R.R. Passenger Corp. v. Bos. & Main Corp.","cite":"503 U.S. 407","y":1992,"id":"1991/90-1419","sc":1,"sum":"In a 6-to-3 decision, the Supreme Court held that the ICC was entitled to deference and that its decision had been reasonable. In the majority opinion, Justice Anthony Kennedy wrote that by interpreting the statute's use of \"required\" to mean that the track must be useful but not absolutely indispensable to Amtrak's operation, the ICC had better accommodated the underlying intention of the RPSA than the appeals court.","sumSrc":"Oyez","by":{"0":"28, 48, 49","2":"55"}},{"t":"case","label":"Owasso Indep. Sch. Dist. No. 1 v. Falvo","cite":"534 U.S. 426","y":2002,"id":"2001/00-1073","sc":1,"sum":"The Court held that Peer grading does not violate FERPA. The Court reasoned that peer-graded items did not constitute education records protected by FERPA until a teacher collected the grades on the students' papers or other items and recorded the grades in the teacher's grade book.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Pa. Co. for Ins. on Lives & Granting Annuities v. Rothensies","cite":"146 F.2d 148","y":1944,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/146/148/","by":{"0":"31"}},{"t":"case","label":"Republic of Iraq v. Beaty","cite":"556 U.S. 848","y":2009,"id":"2008/07-1090","sc":1,"sum":"Explaining that “Congress has in other statutes provided explicitly” that statutes “sunset on a particular date”.","sumSrc":"brief:0","by":{"0":"33"}},{"t":"case","label":"Roberts v. Sea-Land Servs., Inc.","cite":"566 U.S. 93","y":2012,"id":"2011/10-1399","sc":1,"op":1,"sum":"The Court held that the Longshore Act sets the period when an injured worker is awarded disability compensation as the fiscal year when the worker first becomes entitled to compensation.","sumSrc":"Oyez","by":{"0":"passim","2":"21, 24","3":"5, 13"}},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"sum":"Authored by Justice Clarence Thomas, the Court ruled that because the term \"employees,\" as used Title VII of the Civil Rights Act of 1964, includes former employees, Robinson may sue Shell for its allegedly retaliatory post-employment actions.","sumSrc":"Oyez","by":{"0":"26","2":"27"}},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"sum":"Section 3147 does not divest sentencing judges of their § 3651 authority. Nothing in the language of the two provisions suggests the existence of an \"irreconcilable conflict\" from which an intent to work an implicit partial repeal of § 3651 may be inferred; to the contrary, the provisions fit together quite sensibly. Moreover, the totality of the legislative history of the Act of which §3147 is a part demonstrates …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"SAS Inst. Inc. v. Iancu","cite":"138 S. Ct. 1348","y":2018,"id":"2017/16-969","sc":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"0":"46","2":"53"}},{"t":"case","label":"Sessions v. Morales-Santana","cite":"137 S. Ct. 1678","y":2017,"id":"2016/15-1191","sc":1,"sum":"The Court held that statutory distinction between the physical presence requirements for transferral of derivative citizenship for unwed citizen mothers and unwed citizen fathers of foreign-born children violates the Equal Protection Clause of the Fifth Amendment, and it is up to Congress, rather than the courts, to create a uniform solution that does not disadvantage any person on the basis of gender.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Sherley v. Sebelius","cite":"644 F.3d 388","y":2011,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/644/388/","by":{"0":"49"}},{"t":"case","label":"Sinclair Wyo. Ref. Co. v. EPA","cite":"887 F.3d 986","y":2017,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/887/986/","op":1,"by":{"0":"9, 11, 14, 41","1":"26","2":"13"}},{"t":"case","label":"Star Athletica, L.L.C. v. Varsity Brands, Inc.","cite":"137 S. Ct. 1002","y":2017,"id":"2016/15-866","sc":1,"sum":"The Court determined that the test for deciding whether a feature of a “useful article” is copyrightable under the Copyright Act is whether the feature can be perceived as a two- or three-dimensional artwork that is separable from the useful article and if it would be a protectable pictorial, graphical, or sculptural work on its own.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Sturgeon v. Frost","cite":"136 S. Ct. 1061","y":2016,"id":"2015/14-1209","sc":1,"sum":"The Court held that the Alaska National Interest Lands Conservation Act of 1980 did not allow the National Park Service to regulate all land physically within the boundaries of the National Park System in Alaska.","sumSrc":"Oyez","by":{"0":"19, 45"}},{"t":"case","label":"Tyler v. Cain","cite":"533 U.S. 656","y":2001,"id":"2000/00-5961","sc":1,"sum":"The Court held that the Cage rule was not \"made retroactive to cases on collateral review by the Supreme Court.\" Justice Thomas wrote for the Court that \"[b]ecause 'made' means 'held'...it is clear that the Cage rule has not been 'made retroactive to cases on collateral review by the Supreme Court.' Cage itself does not hold that it is retroactive.","sumSrc":"Oyez","by":{"0":"32","3":"11"}},{"t":"case","label":"Page United States v. Cleveland Indians Baseball Co.","cite":"532 U.S. 200","y":2001,"id":"2000/00-203","sc":1,"sum":"The Court held that back wages are subject to FICA and FUTA taxes by reference to the year the wages are in fact paid. \"Although the regulations, like the statute, do not specifically address backpay, the Internal Revenue Service has consistently interpreted them to require taxation of back wages according to the year the wages are actually paid, regardless of when those wages were earned or should have been paid,\" wrote Justice Ginsburg for the Court.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"United States v. Kimbell Foods, Inc.","cite":"440 U.S. 715","y":1979,"id":"1978/77-1359","sc":1,"sum":"These cases present the question whether contractual liens arising from certain federal loan programs take precedence over private liens, absent a federal statute that sets priorities. Resolution of this question requires determination of whether federal or state law governs the conflicting claims and, if federal law applies, whether a uniform priority rule should be fashioned or state commercial law should be …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"sum":"The Court held that the \"administrative implementation of a particular statutory provision qualifies for [the greatest level of deference accorded under Chevron U.S.A. Inc. v. Natural Resources Defense Council] when it appears that Congress delegated authority to the agency generally to make rules carrying the force of law, and that the agency interpretation claiming deference was promulgated in the exercise of that authority.\" Justice Souter wrote that \"a tariff classification has no claim to judicial deference under Chevron, there being no indication that Congress intended such a ruling to carry the force of law, but we hold that under Skidmore v. Swift & Co., the ruling is eligible to claim respect according to its persuasiveness.\".","sumSrc":"Oyez","by":{"0":"46","1":"45"}},{"t":"case","label":"United States v. Virginia","cite":"518 U.S. 515","y":1996,"id":"1995/94-1941","sc":1,"op":2,"sum":"The Court found that the Virginia Military Institute's policy of only admitting and serving males was unconstitutional.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Zobrest v. Catalina Foothills Sch. Dist.","cite":"509 U.S. 1","y":1993,"id":"1992/92-94","sc":1,"sum":"The Court held that the Establishment Clause did not bar the school district from providing the requested interpreter.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"law","label":"AND REGULATIONS Families First Coronavirus Response Act, Pub. L. No. 116-127","url":"https://www.govinfo.gov/link/plaw/116/public/127","by":{"0":"33"}},{"t":"law","label":"Coronavirus Aid, Relief, and Economic Security Act, Pub. L. No. 116-136","url":"https://www.govinfo.gov/link/plaw/116/public/136","by":{"0":"30","1":"36"}},{"t":"law","label":"Pub. L. No. 116-260","url":"https://www.govinfo.gov/link/plaw/116/public/260","by":{"0":"30"}},{"t":"law","label":"Pub. L. No. 114-126","url":"https://www.govinfo.gov/link/plaw/114/public/126","by":{"0":"24"}},{"t":"law","label":"Pub. L. No. 110-140","url":"https://www.govinfo.gov/link/plaw/110/public/140","by":{"0":"6, 41","1":"4, 14, 25, 29","2":"6, 45","3":"16, 21"}},{"t":"law","label":"Pub. L. No. 109-364","url":"https://www.govinfo.gov/link/plaw/109/public/364","by":{"0":"33"}},{"t":"usc","label":"12 U.S.C. § 1795e","url":"https://www.law.cornell.edu/uscode/text/12/1795e","subs":["(a)(1)"],"by":{"0":"29"}},{"t":"usc","label":"15 U.S.C. § 78l","url":"https://www.law.cornell.edu/uscode/text/15/78l","subs":["(f)(1)(E)"],"by":{"0":"24"}},{"t":"usc","label":"18 U.S.C. § 892","url":"https://www.law.cornell.edu/uscode/text/18/892","by":{"0":"24"}},{"t":"usc","label":"19 U.S.C. § 2434","url":"https://www.law.cornell.edu/uscode/text/19/2434","subs":["(c)"],"by":{"0":"24"}},{"t":"usc","label":"20 U.S.C. § 4516","url":"https://www.law.cornell.edu/uscode/text/20/4516","subs":["(e)"],"by":{"0":"29"}},{"t":"usc","label":"22 U.S.C. § 4061","url":"https://www.law.cornell.edu/uscode/text/22/4061","subs":["(a)"],"by":{"0":"24"}},{"t":"usc","label":"25 U.S.C. § 3204","url":"https://www.law.cornell.edu/uscode/text/25/3204","subs":["(b)(3)"],"by":{"0":"24"}},{"t":"usc","label":"32 U.S.C. § 308","url":"https://www.law.cornell.edu/uscode/text/32/308","subs":["(a)"],"by":{"0":"24"}},{"t":"usc","label":"38 U.S.C. § 3748","url":"https://www.law.cornell.edu/uscode/text/38/3748","by":{"0":"24"}},{"t":"usc","label":"42 U.S.C. § 247d-7f","url":"https://www.law.cornell.edu/uscode/text/42/247d-7f","subs":["(b)"],"by":{"0":"33"}},{"t":"usc","label":"43 U.S.C. § 451b","url":"https://www.law.cornell.edu/uscode/text/43/451b","subs":["(c)"],"by":{"0":"24"}},{"t":"usc","label":"47 U.S.C. § 1455","url":"https://www.law.cornell.edu/uscode/text/47/1455","subs":["(b)(1)"],"by":{"0":"29"}},{"t":"usc","label":"50 U.S.C. § 2333","url":"https://www.law.cornell.edu/uscode/text/50/2333","subs":["(c)"],"by":{"0":"24"}},{"t":"reg","label":"40 C.F.R. § 80.1401","url":"https://www.ecfr.gov/current/title-40/section-80.1401","by":{"0":"7, 13"}},{"t":"reg","label":"40 C.F.R. § 80.1441","url":"https://www.ecfr.gov/current/title-40/section-80.1441","subs":["(e)(2)"],"by":{"0":"13"}},{"t":"reg","label":"82 Fed. Reg. 58,486","url":"https://www.govinfo.gov/link/fr/82/58486","by":{"0":"8, 44"}},{"t":"reg","label":"79 Fed. Reg. 42,128","url":"https://www.govinfo.gov/link/fr/79/42128","by":{"0":"13, 43, 47, 48, 49","1":"45, 46","2":"41, 53, 56, 57","3":"12, 21"}},{"t":"reg","label":"78 Fed. Reg. 36,042","url":"https://www.govinfo.gov/link/fr/78/36042","by":{"0":"47","2":"56"}},{"t":"reg","label":"75 Fed. Reg. 14,670","url":"https://www.govinfo.gov/link/fr/75/14670","by":{"0":"12, 13, 43","1":"27"}},{"t":"rule","label":"Fed. R. Civ. P. 6","url":"https://www.law.cornell.edu/rules/frcp/rule_6","subs":["(b)(1)(B)"],"by":{"0":"29"}},{"t":"case","label":"Americans for Clean Energy v. EPA","cite":"864 F.3d 691","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/864/691/","ar":1,"sum":"Rejecting attempt to “bootstrap the definition” of an RFS term “into a boundless general waiver authority”.","sumSrc":"brief:1","by":{"1":"5, 25, 26, 29, 40, 41","2":"passim"}},{"t":"case","label":"Caraco Pharm. Labs., Ltd. v. Novo Nordisk A/S","cite":"566 U.S. 399","y":2012,"id":"2011/10-844","sc":1,"op":1,"sum":"The Court held that counterclaims that challenge unpatented uses of generic drugs, even if other approved uses are still under patent, are allowable under the Hatch-Waxman Act.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"Cochise Consultancy, Inc. v. United States ex rel. Hunt","cite":"139 S. Ct. 1507","y":2019,"id":"2018/18-315","sc":1,"sum":"The limitations period in 31 U. S. C. §3731(b)(2)—which provides that a False Claims Act action must be brought within 3 years after the “the official of the United States charged with responsibility to act in the circumstances” knew or should have known the relevant facts, but not more than 10 years after the violation—applies in a qui tam suit in which the Federal Government has declined to intervene; the relator in a nonintervened suit is not “the official of the United States” whose knowledge triggers §3731(b)(2)’s limitations period.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"32","2":"34"}},{"t":"case","label":"Commissioner v. Asphalt Prods. Co.","cite":"482 U.S. 117","y":1987,"id":"1986/86-1053","sc":1,"sum":"Section 6653(a)(1)'s plain language-whereby, if \"any part of any underpayment\" is due to negligence, the Commissioner shall add to the tax a penalty of \"5 percent of the underpayment\" -clearly establishes that the penalty is imposed on the entire amount of \"the underpayment,\" not just on the \"part of [the] underpayment\" attributable to negligence. This conclusion is supported by the Government's plausible interest …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"34"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"ar":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"1":"46, 47"}},{"t":"case","label":"FCC v. AT&T Inc.","cite":"562 U.S. 397","y":2011,"id":"2010/09-1279","sc":1,"op":1,"sum":"The Court held that corporations do not have a right of personal privacy that would prevent the disclosure of public records handed over to federal agencies.","sumSrc":"Oyez","by":{"1":"20, 36","2":"23, 24, 33"}},{"t":"case","label":"Federal Republic of Germany v. Philipp","cite":"141 S. Ct. 703","y":2021,"id":"2020/19-351","sc":1,"sum":"The Foreign Sovereign Immunities Act’s expropriation exception, 28 U. S. C. §1605(a)(3), incorporates the domestic takings rule, which recognizes that a foreign sovereign’s taking of its own nationals’ property is not a violation of international law.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"34"}},{"t":"case","label":"Freeman v. Quicken Loans, Inc.","cite":"566 U.S. 624","y":2012,"id":"2011/10-1042","sc":1,"op":1,"sum":"The Court held that Section 8(b) of the Real Estate Settlement Procedures Act prohibits a real estate service provider from charging an unearned fee if the fee is divided between two or more parties.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Global Tel*Link v. FCC","cite":"866 F.3d 397","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/866/397/","by":{"1":"47"}},{"t":"case","label":"Guedes v. Bureau of Alcohol, Tobacco, Firearms & Explosives","cite":"140 S. Ct. 789","y":2020,"url":"https://www.courtlistener.com/c/S.%20Ct./140/789/","sc":1,"by":{"1":"46","2":"54, 55"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"op":2,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"1":"20, 21, 32","2":"35"}},{"t":"case","label":"Lomax v. Ortiz-Marquez","cite":"140 S. Ct. 1721","y":2020,"id":"2019/18-8369","sc":1,"sum":"The Court held that a dismissal without prejudice for failure to state a claim counts as a strike under the Prison Litigation Reform Act, 28 U.S.C. § 1915(g), which bars inmates from filing or appealing a federal civil action without paying the associated fees if they have filed three or more cases or appeals that were dismissed because the lawsuits were frivolous or malicious or did not properly state a legal claim for relief.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Milner v. Department of the Navy","cite":"562 U.S. 562","y":2011,"id":"2010/09-1163","sc":1,"sum":"The Court held that documents related to the effect of explosions from Navy exercises did not qualify for withholding under Exception 2 of the Freedom of Information Act.","sumSrc":"Oyez","by":{"1":"20, 33"}},{"t":"case","label":"Mohamad v. Palestinian Auth.","cite":"566 U.S. 449","y":2012,"id":"2011/11-88","sc":1,"op":1,"sum":"The Court held that the word \"individual\" in the Torture Victim Protection Act means a natural person and does not impose any liability against organizations.","sumSrc":"Oyez","by":{"1":"21, 34","2":"35","3":"9"}},{"t":"case","label":"Mohasco Corp. v. Silver","cite":"447 U.S. 807","y":1980,"id":"1979/79-616","sc":1,"sum":"A literal reading of §§ 706 (c) and (e) so as to give the word \"filed\" the same meaning in both subsections gives full effect to the several policies reflected in the Act. Under this literal reading, respondent's charge was not timely filed, because it was \"filed\" on the 351st day (60 days after June 15, 1976, or the earliest date upon which the EEOC could allow the charge to be filed), by which time the applicable …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"Nielsen v. Preap","cite":"139 S. Ct. 954","y":2019,"id":"2018/16-1363","sc":1,"sum":"The Ninth Circuit’s judgments—that respondents, who are deportable for certain specified crimes, are not subject to 8 U. S. C. §1226(c)(2)’s mandatory-detention requirement because they were not arrested by immigration officials as soon as they were released from jail—are reversed, and the cases are remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"37"}},{"t":"case","label":"Pereira v. Sessions","cite":"138 S. Ct. 2105","y":2018,"id":"2017/17-459","sc":1,"sum":"The Court held that a notice to appear for a removal hearing that does not specify the place and time of the hearing does not trigger the stop-time rule of 8 U.S.C. § 1229b(b)(1), which gives the attorney general discretion to cancel removal for an alien who, among other criteria, has been continuously physically present in the country for at least ten years.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Taniguchi v. Kan Pac. Saipan, Ltd.","cite":"566 U.S. 560","y":2012,"id":"2011/10-1472","sc":1,"op":2,"sum":"The Court held that the winner of a federal-court lawsuit cannot be reimbursed by the losing party for any document translation costs under 28 U.S.C. § 1920(6).","sumSrc":"Oyez","by":{"1":"18, 20, 34, 36","2":"24","3":"9"}},{"t":"case","label":"United States v. Briggs","cite":"141 S. Ct. 467","y":2020,"id":"2020/19-108","sc":1,"sum":"Respondents’ prosecutions for military rape were timely commenced under the Uniform Code of Military Justice’s statute of limitations.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"30"}},{"t":"case","label":"Utility Air Regulatory Grp. v. EPA","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"sum":"The Court held that, under the Clean Air Act, the EPA is not required to include greenhouse gas emissions every time it mentions air pollution.","sumSrc":"Oyez","by":{"1":"32","2":"38"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"1":"10"}},{"t":"usc","label":"42 U.S.C. § 7401","url":"https://www.law.cornell.edu/uscode/text/42/7401","by":{"1":"3"}},{"t":"usc","label":"42 U.S.C. § 7545","url":"https://www.law.cornell.edu/uscode/text/42/7545","subs":["(c)(4)(C)(ii)(III)","(h)(5)(C)(ii)","(k)(6)(A)(ii)","(k)(6)(B)(iii)","(m)(3)(C)(ii)","(m)(3)(C)(iii)","(o)(1)(J)","(o)(1)(K)","(o)(2)","(o)(2)(B)","(o)(3)(B)","(o)(3)(B)(i)","(o)(3)(C)","(o)(5)","(o)(5)(D)","(o)(6)","(o)(7)(A)","(o)(7)(B)","(o)(7)(C)","(o)(7)(E)(ii)","(o)(7)(E)(iii)","(o)(9)","(o)(9)(A)","(o)(9)(A)(i)","(o)(9)(A)(ii)","(o)(9)(A)(ii)(I)","(o)(9)(A)(ii)(II)","(o)(9)(B)","(o)(9)(B)(i)","(o)(9)(B)(ii)","(o)(9)(B)(iii)","(o)(9)(C)","(o)(9)(D)","(o)(3)(C)(ii)"],"stext":{"head":"§7545. Regulation of fuels","paras":[[0,"(a) Authority of Administrator to regulate"],[0,"The Administrator may by regulation designate any fuel or fuel additive (including any fuel or fuel additive used exclusively in nonroad engines or nonroad vehicles) and, after such date or dates as may be prescribed by him, no manufacturer or processor of any such fuel or additive may sell, offer for sale, or introduce into commerce such fuel or additive unless the Administrator has registered such fuel or additive in accordance with subsection (b) of this section."],[0,"(b) Registration requirement"],[0,"(1) For the purpose of registration of fuels and fuel additives, the Administrator shall require—"],[1,"(A) the manufacturer of any fuel to notify him as to the commercial identifying name and manufacturer of any additive contained in such fuel; the range of concentration of any additive in the fuel; and the purpose-in-use of any such additive; and"],[1,"(B) the manufacturer of any additive to notify him as to the chemical composition of such additive."],[0,"(2) For the purpose of registration of fuels and fuel additives, the Administrator shall, on a regular basis, require the manufacturer of any fuel or fuel additive—"],[1,"(A) to conduct tests to determine potential public health and environmental effects of the fuel or additive (including carcinogenic, teratogenic, or mutagenic effects); and"],[1,"(B) to furnish the description of any analytical technique that can be used to detect and measure any additive in such fuel, the recommended range of concentration of such additive, and the recommended purpose-in-use of such additive, and such other information as is reasonable and necessary to determine the emissions resulting from the use of the fuel or additive contained in such fuel, the effect of such fuel or additive on the emission control performance of any vehicle, vehicle engine, nonroad engine or nonroad vehicle, or the extent to which such emissions affect the public health or welfare."],[0,"Tests under subparagraph (A) shall be conducted in conformity with test procedures and protocols established by the Administrator. The result of such tests shall not be considered confidential."],[0,"(3) Upon compliance with the provision of this subsection, including assurances that the Administrator will receive changes in the information required, the Administrator shall register such fuel or fuel additive."],[0,"(4) Study on certain fuel additives and blendstocks.—"],[1,"(A) In general.—Not later than 2 years after August 8, 2005, the Administrator shall—"],[2,"(i) conduct a study on the effects on public health (including the effects on children, pregnant women, minority or low-income communities, and other sensitive populations), air quality, and water resources of increased use of, and the feasibility of using as substitutes for methyl tertiary butyl ether in gasoline—"],[3,"(I) ethyl tertiary butyl ether;"],[3,"(II) tertiary amyl methyl ether;"],[3,"(III) di-isopropyl ether;"],[3,"(IV) tertiary butyl alcohol;"],[3,"(V) other ethers and heavy alcohols, as determined by then 1 Administrator;"],[3,"(VI) ethanol;"],[3,"(VII) iso-octane; and"],[3,"(VIII) alkylates; and"],[2,"(ii) conduct a study on the effects on public health (including the effects on children, pregnant women, minority or low-income communities, and other sensitive populations), air quality, and water resources of the adjustment for ethanol-blended reformulated gasoline to the volatile organic compounds performance requirements that are applicable under paragraphs (1) and (3) of subsection (k); and"],[2,"(iii) submit to the Committee on Environment and Public Works of the Senate and the Committee on Energy and Commerce of the House of Representatives a report describing the results of the studies under clauses (i) and (ii)."],[1,"(B) Contracts for study.—In carrying out this paragraph, the Administrator may enter into one or more contracts with nongovernmental entities such as—"],[2,"(i) the national energy laboratories; and"],[2,"(ii) institutions of higher education (as defined in section 1001 of title 20)."],[0,"(c) Offending fuels and fuel additives; control; prohibition"],[0,"(1) The Administrator may, from time to time on the basis of information obtained under subsection (b) of this section or other information available to him, by regulation, control or prohibit the manufacture, introduction into commerce, offering for sale, or sale of any fuel or fuel additive for use in a motor vehicle, motor vehicle engine, or nonroad engine or nonroad vehicle if, in the judgment of the Administrator, any fuel or fuel additive or any emission product of such fuel or fuel additive causes, or contributes, to air pollution or water pollution (including any degradation in the quality of groundwater) that may reasonably be anticipated to endanger the public health or welfare, or (B) 2 if emission products of such fuel or fuel additive will impair to a significant degree the performance of any emission control device or system which is in general use, or which the Administrator finds has been developed to a point where in a reasonable time it would be in general use were such regulation to be promulgated."],[0,"(2)(A) No fuel, class of fuels, or fuel additive may be controlled or prohibited by the Administrator pursuant to clause (A) of paragraph (1) except after consideration of all relevant medical and scientific evidence available to him, including consideration of other technologically or economically feasible means of achieving emission standards under section 7521 of this title."],[0,"(B) No fuel or fuel additive may be controlled or prohibited by the Administrator pursuant to clause (B) of paragraph (1) except after consideration of available scientific and economic data, including a cost benefit analysis comparing emission control devices or systems which are or will be in general use and require the proposed control or prohibition with emission control devices or systems which are or will be in general use and do not require the proposed control or prohibition. On request of a manufacturer of motor vehicles, motor vehicle engines, fuels, or fuel additives submitted within 10 days of notice of proposed rulemaking, the Administrator shall hold a public hearing and publish findings with respect to any matter he is required to consider under this subparagraph. Such findings shall be published at the time of promulgation of final regulations."],[0,"(C) No fuel or fuel additive may be prohibited by the Administrator under paragraph (1) unless he finds, and publishes such finding, that in his judgment such prohibition will not cause the use of any other fuel or fuel additive which will produce emissions which will endanger the public health or welfare to the same or greater degree than the use of the fuel or fuel additive proposed to be prohibited."],[0,"(3)(A) For the purpose of obtaining evidence and data to carry out paragraph (2), the Administrator may require the manufacturer of any motor vehicle or motor vehicle engine to furnish any information which has been developed concerning the emissions from motor vehicles resulting from the use of any fuel or fuel additive, or the effect of such use on the performance of any emission control device or system."],[0,"(B) In obtaining information under subparagraph (A), section 7607(a) of this title (relating to subpenas) shall be applicable."],[0,"(4)(A) Except as otherwise provided in subparagraph (B) or (C), no State (or political subdivision thereof) may prescribe or attempt to enforce, for purposes of motor vehicle emission control, any control or prohibition respecting any characteristic or component of a fuel or fuel additive in a motor vehicle or motor vehicle engine—"],[1,"(i) if the Administrator has found that no control or prohibition of the characteristic or component of a fuel or fuel additive under paragraph (1) is necessary and has published his finding in the Federal Register, or"],[1,"(ii) if the Administrator has prescribed under paragraph (1) a control or prohibition applicable to such characteristic or component of a fuel or fuel additive, unless State prohibition or control is identical to the prohibition or control prescribed by the Administrator."],[0,"(B) Any State for which application of section 7543(a) of this title has at any time been waived under section 7543(b) of this title may at any time prescribe and enforce, for the purpose of motor vehicle emission control, a control or prohibition respecting any fuel or fuel additive."],[0,"(C)(i) A State may prescribe and enforce, for purposes of motor vehicle emission control, a control or prohibition respecting the use of a fuel or fuel additive in a motor vehicle or motor vehicle engine if an applicable implementation plan for such State under section 7410 of this title so provides. The Administrator may approve such provision in an implementation plan, or promulgate an implementation plan containing such a provision, only if he finds that the State control or prohibition is necessary to achieve the national primary or secondary ambient air quality standard which the plan implements. The Administrator may find that a State control or prohibition is necessary to achieve that standard if no other measures that would bring about timely attainment exist, or if other measures exist and are technically possible to implement, but are unreasonable or impracticable. The Administrator may make a finding of necessity under this subparagraph even if the plan for the area does not contain an approved demonstration of timely attainment."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7545?type=usc&year=mostrecent&link-type=html"},"op":9,"head":"§7545. Regulation of fuels","tname":"The Public Health and Welfare","by":{"1":"20, 31, 31, 31, 20, 20, 20, 20, 31, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36","3":"2, 15"}},{"t":"law","label":"Pub. L. No. 109-58","url":"https://www.govinfo.gov/link/plaw/109/public/58","by":{"1":"4","2":"27, 45"}},{"t":"case","label":"Advocate Health Care Network v. Stapleton","cite":"137 S. Ct. 1652","y":2017,"id":"2016/16-74","sc":1,"op":1,"sum":"The Court determined that the “church plan” exemption of the Employee Retirement Income Security Act of 1974 (ERISA) applies to plans that are maintained by a qualifying church-affiliated organization, even if that organization did not originally establish the plan.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"Alon Reﬁning Krotz Springs, Inc. v. EPA","cite":"936 F.3d 628","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/936/628/","by":{"2":"6, 8"}},{"t":"case","label":"American Fuel & Petrochemical Mfrs. v. EPA","cite":"937 F.3d 559","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/937/559/","op":3,"ar":1,"by":{"2":"7, 46"}},{"t":"case","label":"Aquilent, Inc. v. Distributed Solutions, Inc.","cite":"2012 WL 405009","y":2012,"court":"E.D. Va. Feb. 7","by":{"2":"31"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"sum":"The Court held that an federal habeas corpus petition is not an \"application for State post-conviction or other collateral review\" within the meaning of 28 USC section 2244(d)(2). \"Section 2244(d)(2) therefore did not toll the limitation period during the pendency of [Walker's] first federal habeas petition,\" wrote Justice O'Connor. \"[I]f the statute were construed so as to give applications for federal review the same tolling effect as applications for state collateral review, then [section] 2244(d)(2) would furnish little incentive for individuals to seek relief from the state courts before filing federal habeas petitions,\" concluded Justice O'Connor.","sumSrc":"Oyez","by":{"2":"38"}},{"t":"case","label":"Eastham v. Chesapeake Appalachia, L.L.C.","cite":"754 F.3d 356","y":2014,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/754/356/","by":{"2":"31"}},{"t":"case","label":"Grifﬁn v. Oceanic Contractors, Inc.","cite":"458 U.S. 564","y":1982,"id":"1981/81-614","sc":1,"sum":"The district courts have no discretion to limit the period during which the wage penalty is assessed. Imposition of the penalty is mandatory for each day that payment is withheld in violation of § 596.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"40"}},{"t":"case","label":"IBP, Inc. v. Alvarez","cite":"546 U.S. 21","y":2005,"id":"2005/03-1238","sc":1,"sum":"Justice John Paul Stevens, for a unanimous Court, wrote that putting on required safety equipment qualified as a \"principal activity\" under the FLSA. The workday began when employees started that activity and therefore included the subsequent time spent walking to the worksite.","sumSrc":"Oyez","by":{"2":"35"}},{"t":"case","label":"Lujan v. Nat’l Wildlife Fed’n","cite":"497 U.S. 871","y":1990,"id":"1989/89-640","sc":1,"sum":"In a 5-to-4 decision written by Justice Antonin Scalia, the Supreme Court held that NWF did not have standing to challenge the land-use designations. The two timely affidavits were not enough to show that the group members had actually been affected by the BLM decisions.","sumSrc":"Oyez","by":{"2":"32"}},{"t":"case","label":"Merit Mgmt. Grp., LP v. FTI Consulting, Inc.","cite":"138 S. Ct. 883","y":2018,"id":"2017/16-784","sc":1,"sum":"The Court held that the safe harbor provision of 11 U.S.C. § 546(e), which prohibits a trustee from avoiding a transfer made by or to a financial institution, does not include transfers where the benefit and detriment of the transfer impact companies that are not financial institutions.","sumSrc":"Oyez","by":{"2":"34"}},{"t":"case","label":"Monroe Energy, LLC v. EPA","cite":"750 F.3d 909","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/750/909/","by":{"2":"7"}},{"t":"case","label":"N.L.R.B. v. SW Gen., Inc.","cite":"137 S. Ct. 929","y":2017,"id":"2016/15-1251","sc":1,"sum":"The Court determined that the limitations on nominees to vacant positions serving in an acting capacity under the Federal Vacancies Reform Act apply equally to first assistants who take on the position and to those who are selected by the President from within the same agency or from another agency.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Nat’l Ass’n of Mfrs. v. Dep’t of Def.","cite":"138 S. Ct. 617","y":2018,"id":"2017/16-299","sc":1,"sum":"The Court decided that challenges to the Environmental Protection Agency’s rule that defines the scope of United States waters must be filed in federal district courts.","sumSrc":"Oyez","by":{"2":"38"}},{"t":"case","label":"Nijhawan v. Holder","cite":"557 U.S. 29","y":2009,"id":"2008/08-495","sc":1,"sum":"The Court found that when an alien is convicted of conspiracy and held responsible for causing more than $10,000 in damages, the statute requirement used by the Immigration and Nationality Act (INA) to deport the alien is satisfied, even if the $10,000 is not established by a jury.","sumSrc":"Oyez","by":{"2":"35"}},{"t":"case","label":"Parker Drilling Mgmt. Servs., Ltd. v. Newton","cite":"139 S. Ct. 1881","y":2019,"id":"2018/18-389","sc":1,"sum":"Under the Outer Continental Shelf Lands Act, where federal law addresses the relevant issue, state law is not adopted as surrogate federal law on the Outer Continental Shelf.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"24"}},{"t":"case","label":"Rubin v. Islamic Republic of Iran","cite":"138 S. Ct. 816","y":2018,"id":"2017/16-534","sc":1,"sum":"The Court held that 28 U.S.C. § 1610(g) does not provide a freestanding attachment immunity exception that allows terror victim judgment creditors to attach and execute upon assets of foreign state; rather, the immunity of property must be rescinded under a separate provision under that section.","sumSrc":"Oyez","by":{"2":"33"}},{"t":"case","label":"Sandifer v. U.S. Steel Corp.","cite":"571 U.S. 220","y":2015,"id":"2013/12-417","sc":1,"sum":"The Court held that putting on safety garments constitutes \"changing clothes\" under the Fair Labor Standards Act.","sumSrc":"Oyez","by":{"2":"24","3":"17"}},{"t":"case","label":"Sebelius v. Cloer","cite":"569 U.S. 369","y":2013,"id":"2012/12-236","sc":1,"sum":"The Court found that a person who petitions under the National Childhood Vaccine Injury Act can recover attorney's fees regardless of if the petition was ultimately successful.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"State Farm Fire & Cas. Co. v. U.S. ex rel. Rigsby","cite":"137 S. Ct. 436","y":2016,"id":"2016/15-513","sc":1,"sum":"The Court determined that a violation of the False Claims Act’s seal requirement does not mandate dismissal of the complaint.","sumSrc":"Oyez","by":{"2":"47"}},{"t":"case","label":"Sunac Petroleum Corp. v. Parkes","cite":"416 S.W.2d 798","y":1967,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.2d/416/798/","by":{"2":"30"}},{"t":"case","label":"United States v. Hermanek","cite":"289 F.3d 1076","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/289/1076/","by":{"2":"30"}},{"t":"case","label":"United States v. Menasche","cite":"348 U.S. 528","y":1955,"id":"scdb/1954-050","sc":1,"sum":"An alien who filed his declaration of intention to become an American citizen before the effective date of the Immigration and Nationality Act bf 1952, and who otherwise complied with the naturalization laws then in effect, has a \"status,\" \"condition\" or \"right in process 9 f acquisition\" preserved by § 405 (a), the general savings clause of the 1952 Act, even though his petition for naturalization was filed after …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"38"}},{"t":"case","label":"United States v. Ojeda Rios","cite":"875 F.2d 17","y":1989,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/875/17/","by":{"2":"30"}},{"t":"case","label":"Xenia v. State","cite":"746 N.E.2d 666","y":2000,"court":"Ohio Ct. App.","url":"https://www.courtlistener.com/c/N.E.2d/746/666/","by":{"2":"31"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"reg","label":"Federal Register, 77 Fed. Reg. 1,320","url":"https://www.govinfo.gov/link/fr/77/1320","by":{"2":"11, 39"}},{"t":"reg","label":"78 Fed. Reg. 49,794","url":"https://www.govinfo.gov/link/fr/78/49794","by":{"2":"44"}},{"t":"reg","label":"82 Fed. Reg. 34,206","url":"https://www.govinfo.gov/link/fr/82/34206","by":{"2":"49"}},{"t":"reg","label":"85 Fed. Reg. 7,016","url":"https://www.govinfo.gov/link/fr/85/7016","by":{"2":"50","3":"15"}},{"t":"reg","label":"86 Fed. Reg. 5,182","url":"https://www.govinfo.gov/link/fr/86/5182","by":{"2":"51"}},{"t":"case","label":"Bowen v. Georgetown Univ. Hosp.","cite":"488 U.S. 204","y":1988,"id":"1988/87-1097","sc":1,"sum":"Under the Medicare program, the Government reimburses health care providers for expenses incurred in providing medical services to Medicare beneficiaries. The Medicare Act in 42 U. S. C. § 1395x(v)(1)(A) authorizes the Secretary of Health and Human Services (Secretary) to promulgate cost-reimbursement regulations and also provides that \"[s]uch regulations shall... (ii) provide for the making of suitable retroactive …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"22"}},{"t":"case","label":"Ergon-W. Va., Inc. v. EPA","cite":"896 F.3d 600","y":2018,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/896/600/","by":{"3":"18, 19"}},{"t":"case","label":"Geo-Energy Partners-1983 Ltd. v. Kempthorne","cite":"551 F. Supp. 2d 1210","y":2008,"court":"D. Nev.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/551/1210/","by":{"3":"7"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"Perez v. Mortg. Bankers Ass’n","cite":"135 S. Ct. 1199","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1199/","sc":1,"by":{"3":"22"}},{"t":"case","label":"Pub. Utils. Comm’n v. FERC","cite":"24 F.3d 275","y":1994,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/24/275/","by":{"3":"18"}},{"t":"usc","label":"8 U.S.C. § 1184","url":"https://www.law.cornell.edu/uscode/text/8/1184","subs":["(g)(8)(D)"],"stext":{"head":"§1184. Admission of nonimmigrants","paras":[[0,"(a) Regulations"],[0,"(1) The admission to the United States of any alien as a nonimmigrant shall be for such time and under such conditions as the Attorney General may by regulations prescribe, including when he deems necessary the giving of a bond with sufficient surety in such sum and containing such conditions as the Attorney General shall prescribe, to insure that at the expiration of such time or upon failure to maintain the status under which he was admitted, or to maintain any status subsequently acquired under section 1258 of this title, such alien will depart from the United States. No alien admitted to Guam or the Commonwealth of the Northern Mariana Islands without a visa pursuant to section 1182(l) of this title may be authorized to enter or stay in the United States other than in Guam or the Commonwealth of the Northern Mariana Islands or to remain in Guam or the Commonwealth of the Northern Mariana Islands for a period exceeding 45 days from date of admission to Guam or the Commonwealth of the Northern Mariana Islands. No alien admitted to the United States without a visa pursuant to section 1187 of this title may be authorized to remain in the United States as a nonimmigrant visitor for a period exceeding 90 days from the date of admission."],[0,"(2)(A) The period of authorized status as a nonimmigrant described in section 1101(a)(15)(O) of this title shall be for such period as the Attorney General may specify in order to provide for the event (or events) for which the nonimmigrant is admitted."],[0,"(B) The period of authorized status as a nonimmigrant described in section 1101(a)(15)(P) of this title shall be for such period as the Attorney General may specify in order to provide for the competition, event, or performance for which the nonimmigrant is admitted. In the case of nonimmigrants admitted as individual athletes under section 1101(a)(15)(P) of this title, the period of authorized status may be for an initial period (not to exceed 5 years) during which the nonimmigrant will perform as an athlete and such period may be extended by the Attorney General for an additional period of up to 5 years."],[0,"(b) Presumption of status; written waiver"],[0,"Every alien (other than a nonimmigrant described in subparagraph (L) or (V) of section 1101(a)(15) of this title, and other than a nonimmigrant described in any provision of section 1101(a)(15)(H)(i) of this title except subclause (b1) of such section) shall be presumed to be an immigrant until he establishes to the satisfaction of the consular officer, at the time of application for a visa, and the immigration officers, at the time of application for admission, that he is entitled to a nonimmigrant status under section 1101(a)(15) of this title. An alien who is an officer or employee of any foreign government or of any international organization entitled to enjoy privileges, exemptions, and immunities under the International Organizations Immunities Act [22 U.S.C. 288 et seq.], or an alien who is the attendant, servant, employee, or member of the immediate family of any such alien shall not be entitled to apply for or receive an immigrant visa, or to enter the United States as an immigrant unless he executes a written waiver in the same form and substance as is prescribed by section 1257(b) of this title."],[0,"(c) Petition of importing employer"],[0,"(1) The question of importing any alien as a nonimmigrant under subparagraph (H), (L), (O), or (P)(i) of section 1101(a)(15) of this title (excluding nonimmigrants under section 1101(a)(15)(H)(i)(b1) of this title) in any specific case or specific cases shall be determined by the Attorney General, after consultation with appropriate agencies of the Government, upon petition of the importing employer. Such petition, shall be made and approved before the visa is granted. The petition shall be in such form and contain such information as the Attorney General shall prescribe. The approval of such a petition shall not, of itself, be construed as establishing that the alien is a nonimmigrant. For purposes of this subsection with respect to nonimmigrants described in section 1101(a)(15)(H)(ii)(a) of this title, the term \"appropriate agencies of Government\" means the Department of Labor and includes the Department of Agriculture. The provisions of section 1188 of this title shall apply to the question of importing any alien as a nonimmigrant under section 1101(a)(15)(H)(ii)(a) of this title."],[0,"(2)(A) The Attorney General shall provide for a procedure under which an importing employer which meets requirements established by the Attorney General may file a blanket petition to import aliens as nonimmigrants described in section 1101(a)(15)(L) of this title instead of filing individual petitions under paragraph (1) to import such aliens. Such procedure shall permit the expedited processing of visas for admission of aliens covered under such a petition."],[0,"(B) For purposes of section 1101(a)(15)(L) of this title, an alien is considered to be serving in a capacity involving specialized knowledge with respect to a company if the alien has a special knowledge of the company product and its application in international markets or has an advanced level of knowledge of processes and procedures of the company."],[0,"(C) The Attorney General shall provide a process for reviewing and acting upon petitions under this subsection with respect to nonimmigrants described in section 1101(a)(15)(L) of this title within 30 days after the date a completed petition has been filed."],[0,"(D) The period of authorized admission for—"],[1,"(i) a nonimmigrant admitted to render services in a managerial or executive capacity under section 1101(a)(15)(L) of this title shall not exceed 7 years, or"],[1,"(ii) a nonimmigrant admitted to render services in a capacity that involves specialized knowledge under section 1101(a)(15)(L) of this title shall not exceed 5 years."],[0,"(E) In the case of an alien spouse admitted under section 1101(a)(15)(L) of this title, who is accompanying or following to join a principal alien admitted under such section, the Attorney General shall authorize the alien spouse to engage in employment in the United States and provide the spouse with an \"employment authorized\" endorsement or other appropriate work permit."],[0,"(F) An alien who will serve in a capacity involving specialized knowledge with respect to an employer for purposes of section 1101(a)(15)(L) of this title and will be stationed primarily at the worksite of an employer other than the petitioning employer or its affiliate, subsidiary, or parent shall not be eligible for classification under section 1101(a)(15)(L) of this title if—"],[1,"(i) the alien will be controlled and supervised principally by such unaffiliated employer; or"],[1,"(ii) the placement of the alien at the worksite of the unaffiliated employer is essentially an arrangement to provide labor for hire for the unaffiliated employer, rather than a placement in connection with the provision of a product or service for which specialized knowledge specific to the petitioning employer is necessary."],[0,"(3) The Attorney General shall approve a petition—"],[1,"(A) with respect to a nonimmigrant described in section 1101(a)(15)(O)(i) of this title only after consultation in accordance with paragraph (6) or, with respect to aliens seeking entry for a motion picture or television production, after consultation with the appropriate union representing the alien's occupational peers and a management organization in the area of the alien's ability, or"],[1,"(B) with respect to a nonimmigrant described in section 1101(a)(15)(O)(ii) of this title after consultation in accordance with paragraph (6) or, in the case of such an alien seeking entry for a motion picture or television production, after consultation with such a labor organization and a management organization in the area of the alien's ability."],[0,"In the case of an alien seeking entry for a motion picture or television production, (i) any opinion under the previous sentence shall only be advisory, (ii) any such opinion that recommends denial must be in writing, (iii) in making the decision the Attorney General shall consider the exigencies and scheduling of the production, and (iv) the Attorney General shall append to the decision any such opinion. The Attorney General shall provide by regulation for the waiver of the consultation requirement under subparagraph (A) in the case of aliens who have been admitted as nonimmigrants under section 1101(a)(15)(O)(i) of this title because of extraordinary ability in the arts and who seek readmission to perform similar services within 2 years after the date of a consultation under such subparagraph. Not later than 5 days after the date such a waiver is provided, the Attorney General shall forward a copy of the petition and all supporting documentation to the national office of an appropriate labor organization."],[0,"(4)(A) For purposes of section 1101(a)(15)(P)(i)(a) of this title, an alien is described in this subparagraph if the alien—"],[1,"(i)(I) performs as an athlete, individually or as part of a group or team, at an internationally recognized level of performance;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1184?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1184. Admission of nonimmigrants","tname":"Aliens and Nationality","by":{"3":"6"}},{"t":"usc","label":"10 U.S.C. § 2304a","url":"https://www.law.cornell.edu/uscode/text/10/2304a","subs":["(f)"],"op":1,"tname":"Armed Forces","by":{"3":"6"}},{"t":"usc","label":"15 U.S.C. § 78d-5","url":"https://www.law.cornell.edu/uscode/text/15/78d-5","subs":["(a)(2)"],"by":{"3":"6"}},{"t":"usc","label":"19 U.S.C. § 2432","url":"https://www.law.cornell.edu/uscode/text/19/2432","subs":["(d)(1)"],"stext":{"head":"§2432. Freedom of emigration in East-West trade","paras":[[0,"(a) Actions of nonmarket economy countries making them ineligible for normal trade relations, programs of credits, credit guarantees, or investment guarantees, or commercial agreements"],[0,"To assure the continued dedication of the United States to fundamental human rights, and notwithstanding any other provision of law, on or after January 3, 1975, products from any nonmarket economy country shall not be eligible to receive nondiscriminatory treatment (normal trade relations), such country shall not participate in any program of the Government of the United States which extends credits or credit guarantees or investment guarantees, directly or indirectly, and the President of the United States shall not conclude any commercial agreement with any such country, during the period beginning with the date on which the President determines that such country—"],[1,"(1) denies its citizens the right or opportunity to emigrate;"],[1,"(2) imposes more than a nominal tax on emigration or on the visas or other documents required for emigration, for any purpose or cause whatsoever; or"],[1,"(3) imposes more than a nominal tax, levy, fine, fee, or other charge on any citizen as a consequence of the desire of such citizen to emigrate to the country of his choice,"],[0,"and ending on the date on which the President determines that such country is no longer in violation of paragraph (1), (2), or (3)."],[0,"(b) Presidential determination and report to Congress that nation is not violating freedom of emigration"],[0,"After January 3, 1975, (A) products of a nonmarket economy country may be eligible to receive nondiscriminatory treatment (normal trade relations), (B) such country may participate in any program of the Government of the United States which extends credits or credit guarantees or investment guarantees, and (C) the President may conclude a commercial agreement with such country, only after the President has submitted to the Congress a report indicating that such country is not in violation of paragraph (1), (2), or (3) of subsection (a). Such report with respect to such country shall include information as to the nature and implementation of emigration laws and policies and restrictions or discrimination applied to or against persons wishing to emigrate. The report required by this subsection shall be submitted initially as provided herein and, with current information, on or before each June 30 and December 31 thereafter so long as such treatment is received, such credits or guarantees are extended, or such agreement is in effect."],[0,"(c) Waiver authority of President"],[0,"(1) During the 18-month period beginning on January 3, 1975, the President is authorized to waive by Executive order the application of subsections (a) and (b) with respect to any country, if he reports to the Congress that—"],[1,"(A) he has determined that such waiver will substantially promote the objectives of this section; and"],[1,"(B) he has received assurances that the emigration practices of that country will henceforth lead substantially to the achievement of the objectives of this section."],[0,"(2) During any period subsequent to the 18-month period referred to in paragraph (1), the President is authorized to waive by Executive order the application of subsections (a) and (b) with respect to any country, if the waiver authority granted by this subsection continues to apply to such country pursuant to subsection (d), and if he reports to the Congress that—"],[1,"(A) he has determined that such waiver will substantially promote the objectives of this section; and"],[1,"(B) he has received assurances that the emigration practices of that country will henceforth lead substantially to the achievement of the objectives of this section."],[0,"(3) A waiver with respect to any country shall terminate on the day after the waiver authority granted by this subsection ceases to be effective with respect to such country pursuant to subsection (d). The President may, at any time, terminate by Executive order any waiver granted under this subsection."],[0,"(d) Extension of waiver authority"],[0,"(1) If the President determines that the further extension of the waiver authority granted under subsection (c) will substantially promote the objectives of this section, he may recommend further extensions of such authority for successive 12-month periods. Any such recommendations shall—"],[1,"(A) be made not later than 30 days before the expiration of such authority;"],[1,"(B) be made in a document transmitted to the House of Representatives and the Senate setting forth his reasons for recommending the extension of such authority; and"],[1,"(C) include, for each country with respect to which a waiver granted under subsection (c) is in effect, a determination that continuation of the waiver applicable to that country will substantially promote the objectives of this section, and a statement setting forth his reasons for such determination."],[0,"If the President recommends the further extension of such authority, such authority shall continue in effect until the end of the 12-month period following the end of the previous 12-month extension with respect to any country (except for any country with respect to which such authority has not been extended under this subsection), unless a joint resolution described in section 2193(a) of this title is enacted into law pursuant to the provisions of paragraph (2)."],[0,"(2)(A) The requirements of this paragraph are met if the joint resolution is enacted under the procedures set forth in section 2193 of this title, and—"],[1,"(i) the Congress adopts and transmits the joint resolution to the President before the end of the 60-day period beginning on the date the waiver authority would expire but for an extension under paragraph (1), and"],[1,"(ii) if the President vetoes the joint resolution, each House of Congress votes to override such veto on or before the later of the last day of the 60-day period referred to in clause (i) or the last day of the 15-day period (excluding any day described in section 2194(b) of this title) beginning on the date the Congress receives the veto message from the President."],[0,"(B) If a joint resolution is enacted into law under the provisions of this paragraph, the waiver authority applicable to any country with respect to which the joint resolution disapproves of the extension of such authority shall cease to be effective as of the day after the 60-day period beginning on the date of the enactment of the joint resolution."],[0,"(C) A joint resolution to which this subsection and section 2193 of this title apply may be introduced at any time on or after the date the President transmits to the Congress the document described in paragraph (1)(B)."],[0,"(e) Countries not covered"],[0,"This section shall not apply to any country the products of which are eligible for the rates set forth in rate column numbered 1 of the Tariff Schedules of the United States on January 3, 1975."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/19/2432?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2432. Freedom of emigration in East-West trade","tname":"Customs Duties","by":{"3":"7"}},{"t":"usc","label":"28 U.S.C. § 594","url":"https://www.law.cornell.edu/uscode/text/28/594","subs":["(b)(3)(A)"],"stext":{"head":"§594. Authority and duties of an independent counsel","paras":[[0,"(a) Authorities.—Notwithstanding any other provision of law, an independent counsel appointed under this chapter shall have, with respect to all matters in such independent counsel's prosecutorial jurisdiction established under this chapter, full power and independent authority to exercise all investigative and prosecutorial functions and powers of the Department of Justice, the Attorney General, and any other officer or employee of the Department of Justice, except that the Attorney General shall exercise direction or control as to those matters that specifically require the Attorney General's personal action under section 2516 of title 18. Such investigative and prosecutorial functions and powers shall include—"],[1,"(1) conducting proceedings before grand juries and other investigations;"],[1,"(2) participating in court proceedings and engaging in any litigation, including civil and criminal matters, that such independent counsel considers necessary;"],[1,"(3) appealing any decision of a court in any case or proceeding in which such independent counsel participates in an official capacity;"],[1,"(4) reviewing all documentary evidence available from any source;"],[1,"(5) determining whether to contest the assertion of any testimonial privilege;"],[1,"(6) receiving appropriate national security clearances and, if necessary, contesting in court (including, where appropriate, participating in in camera proceedings) any claim of privilege or attempt to withhold evidence on grounds of national security;"],[1,"(7) making applications to any Federal court for a grant of immunity to any witness, consistent with applicable statutory requirements, or for warrants, subpoenas, or other court orders, and, for purposes of sections 6003, 6004, and 6005 of title 18, exercising the authority vested in a United States attorney or the Attorney General;"],[1,"(8) inspecting, obtaining, or using the original or a copy of any tax return, in accordance with the applicable statutes and regulations, and, for purposes of section 6103 of the Internal Revenue Code of 1986 and the regulations issued thereunder, exercising the powers vested in a United States attorney or the Attorney General;"],[1,"(9) initiating and conducting prosecutions in any court of competent jurisdiction, framing and signing indictments, filing informations, and handling all aspects of any case, in the name of the United States; and"],[1,"(10) consulting with the United States attorney for the district in which any violation of law with respect to which the independent counsel is appointed was alleged to have occurred."],[0,"(b) Compensation.—"],[1,"(1) In general.—An independent counsel appointed under this chapter shall receive compensation at the per diem rate equal to the annual rate of basic pay payable for level IV of the Executive Schedule under section 5315 of title 5."],[1,"(2) Travel expenses.—Except as provided in paragraph (3), an independent counsel and persons appointed under subsection (c) shall be entitled to the payment of travel expenses as provided by subchapter I of chapter 57 of title 5, United States Code, including travel, per diem, and subsistence expenses in accordance with section 5703 of title 5."],[1,"(3) Travel to primary office.—"],[2,"(A) In general.—After 1 year of service under this chapter, an independent counsel and persons appointed under subsection (c) shall not be entitled to the payment of travel, per diem, or subsistence expenses under subchapter I of chapter 57 of title 5, United States Code, for the purpose of commuting to or from the city in which the primary office of the independent counsel or person is located. The 1-year period may be extended for successive 6-month periods if the independent counsel and the division of the court certify that the payment is in the public interest to carry out the purposes of this chapter."],[2,"(B) Relevant factors.—In making any certification under this paragraph with respect to travel and subsistence expenses of an independent counsel or person appointed under subsection (c), the independent counsel and the division of the court shall consider, among other relevant factors—"],[3,"(i) the cost to the Government of reimbursing such travel and subsistence expenses;"],[3,"(ii) the period of time for which the independent counsel anticipates that the activities of the independent counsel or person, as the case may be, will continue;"],[3,"(iii) the personal and financial burdens on the independent counsel or person, as the case may be, of relocating so that such travel and subsistence expenses would not be incurred; and"],[3,"(iv) the burdens associated with appointing a new independent counsel, or appointing another person under subsection (c), to replace the individual involved who is unable or unwilling to so relocate."],[0,"(c) Additional Personnel.—For the purposes of carrying out the duties of an office of independent counsel, such independent counsel may appoint, fix the compensation, and assign the duties of such employees as such independent counsel considers necessary (including investigators, attorneys, and part-time consultants). The positions of all such employees are exempted from the competitive service. Such employees shall be compensated at levels not to exceed those payable for comparable positions in the Office of United States Attorney for the District of Columbia under sections 548 and 550, but in no event shall any such employee be compensated at a rate greater than the rate of basic pay payable for level ES–4 of the Senior Executive Service Schedule under section 5382 of title 5, as adjusted for the District of Columbia under section 5304 of that title regardless of the locality in which an employee is employed."],[0,"(d) Assistance of Department of Justice.—"],[1,"(1) In carrying out functions.—An independent counsel may request assistance from the Department of Justice in carrying out the functions of the independent counsel, and the Department of Justice shall provide that assistance, which may include access to any records, files, or other materials relevant to matters within such independent counsel's prosecutorial jurisdiction, and the use of the resources and personnel necessary to perform such independent counsel's duties. At the request of an independent counsel, prosecutors, administrative personnel, and other employees of the Department of Justice may be detailed to the staff of the independent counsel."],[1,"(2) Payment of and reports on expenditures of independent counsel.—The Department of Justice shall pay all costs relating to the establishment and operation of any office of independent counsel. The Attorney General shall submit to the Congress, not later than 30 days after the end of each fiscal year, a report on amounts paid during that fiscal year for expenses of investigations and prosecutions by independent counsel. Each such report shall include a statement of all payments made for activities of independent counsel but may not reveal the identity or prosecutorial jurisdiction of any independent counsel which has not been disclosed under section 593(b)(4)."],[0,"(e) Referral of Other Matters to an Independent Counsel.—An independent counsel may ask the Attorney General or the division of the court to refer to the independent counsel matters related to the independent counsel's prosecutorial jurisdiction, and the Attorney General or the division of the court, as the case may be, may refer such matters. If the Attorney General refers a matter to an independent counsel on the Attorney General's own initiative, the independent counsel may accept such referral if the matter relates to the independent counsel's prosecutorial jurisdiction. If the Attorney General refers any matter to the independent counsel pursuant to the independent counsel's request, or if the independent counsel accepts a referral made by the Attorney General on the Attorney General's own initiative, the independent counsel shall so notify the division of the court."],[0,"(f) Compliance With Policies of the Department of Justice.—"],[1,"(1) In general.—An independent counsel shall, except to the extent that to do so would be inconsistent with the purposes of this chapter, comply with the written or other established policies of the Department of Justice respecting enforcement of the criminal laws. To determine these policies and policies under subsection (l)(1)(B), the independent counsel shall, except to the extent that doing so would be inconsistent with the purposes of this chapter, consult with the Department of Justice."],[1,"(2) National security.—An independent counsel shall comply with guidelines and procedures used by the Department in the handling and use of classified material."],[0,"(g) Dismissal of Matters.—The independent counsel shall have full authority to dismiss matters within the independent counsel's prosecutorial jurisdiction without conducting an investigation or at any subsequent time before prosecution, if to do so would be consistent with the written or other established policies of the Department of Justice with respect to the enforcement of criminal laws."],[0,"(h) Reports by Independent Counsel.—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/594?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§594. Authority and duties of an independent counsel","tname":"Judiciary and Judicial Procedure","by":{"3":"7"}},{"t":"usc","label":"49 U.S.C. § 44506","url":"https://www.law.cornell.edu/uscode/text/49/44506","subs":["(c)(2)(B)"],"by":{"3":"7"}},{"t":"usc","label":"50 U.S.C. § 3024","url":"https://www.law.cornell.edu/uscode/text/50/3024","subs":["(n)(4)(E)(ii)"],"by":{"3":"7"}},{"t":"reg","label":"40 C.F.R. § 80.1427","url":"https://www.ecfr.gov/current/title-40/section-80.1427","subs":["(b)"],"by":{"3":"20"}},{"t":"reg","label":"77 Fed. Reg. 70,752","url":"https://www.govinfo.gov/link/fr/77/70752","by":{"3":"19"}}]};